import{_ as t,o as s,c as e,a3 as r}from"./chunks/framework.CVt6dz2a.js";const c=JSON.parse('{"title":"学习路径建议","description":"","frontmatter":{},"headers":[],"relativePath":"learning-path.md","filePath":"learning-path.md","lastUpdated":1792595797000}'),h={name:"learning-path.md"};function p(b,a,l,g,i,d){return s(),e("div",null,[...a[0]||(a[0]=[r('<h1 id="学习路径建议" tabindex="-1">学习路径建议 <a class="header-anchor" href="#学习路径建议" aria-label="Permalink to &quot;学习路径建议&quot;">​</a></h1><p>Three.js 的知识点看似庞杂，但只要遵循&quot;<strong>先搭骨架，再长血肉</strong>&quot;的顺序，学习曲线可以非常平滑。本教程把内容组织为 <strong>11 个模块 × 3 个阶段</strong>，并给出推荐的学习节奏与自测标准。</p><h2 id="三个阶段分别学什么" tabindex="-1">三个阶段分别学什么 <a class="header-anchor" href="#三个阶段分别学什么" aria-label="Permalink to &quot;三个阶段分别学什么&quot;">​</a></h2><div class="path-legend"><span><b class="path-stage path-stage--base">基础</b> 建立概念，能跑通最小示例</span><span><b class="path-stage path-stage--adv">进阶</b> 理解原理，掌握可调参数</span><span><b class="path-stage path-stage--pra">实战</b> 组合知识，完成小作品</span></div><ul><li><strong>基础入门</strong>：回答&quot;它是什么、什么时候用&quot;，每个概念配一个 20 行左右的最小示例。</li><li><strong>进阶应用</strong>：回答&quot;参数怎么调、底层怎么运作&quot;，引入多个对象之间的协作关系。</li><li><strong>实战案例</strong>：回答&quot;怎么组合起来做东西&quot;，每章产出一个可交互的小案例。</li></ul><h2 id="推荐学习顺序-四周计划" tabindex="-1">推荐学习顺序（四周计划） <a class="header-anchor" href="#推荐学习顺序-四周计划" aria-label="Permalink to &quot;推荐学习顺序（四周计划）&quot;">​</a></h2><p>下表给出建议顺序、依赖关系与检验标准。每天投入 45–60 分钟，约四周可完成全部内容。</p><table tabindex="0"><thead><tr><th>周次</th><th>模块</th><th>为什么是这个顺序</th><th>学完的检验标准</th></tr></thead><tbody><tr><td>第 1 周</td><td>① 认识 → ② 场景 → ③ 相机 → ④ 渲染器</td><td>先打通&quot;场景→相机→渲染器→画面&quot;这条最小管线，这是所有 Three.js 程序的骨架</td><td>不看教程能手写一个旋转立方体页面</td></tr><tr><td>第 2 周</td><td>⑤ 几何体 → ⑥ 材质 → ⑦ 纹理</td><td>解决&quot;画面里放什么、它长什么样&quot;，三者共同决定物体外观</td><td>能为物体贴上自制图案并解释 UV 是什么</td></tr><tr><td>第 3 周</td><td>⑧ 灯光 → ⑨ 动画</td><td>先让静态场景有明暗质感，再让它动起来，符合观察习惯</td><td>能做出带阴影、可循环播放的关键帧动画</td></tr><tr><td>第 4 周</td><td>⑩ 交互 → ⑪ 综合实战</td><td>最后处理用户输入，把前面所有模块组装成完整作品</td><td>完成一个可旋转、可点击的 3D 场景小作品</td></tr></tbody></table><h2 id="完整模块索引" tabindex="-1">完整模块索引 <a class="header-anchor" href="#完整模块索引" aria-label="Permalink to &quot;完整模块索引&quot;">​</a></h2><div class="path-grid"><a class="path-card" href="/guide/01-intro/basics"><h4>① 认识 Three.js</h4><p><b class="path-stage path-stage--base">基础</b>第一个场景<br><b class="path-stage path-stage--adv">进阶</b>工程化与调试<br><b class="path-stage path-stage--pra">实战</b>开发模板</p></a><a class="path-card" href="/guide/02-scene/basics"><h4>② 场景 Scene</h4><p><b class="path-stage path-stage--base">基础</b>场景图与坐标<br><b class="path-stage path-stage--adv">进阶</b>层级矩阵与雾<br><b class="path-stage path-stage--pra">实战</b>太阳系模型</p></a><a class="path-card" href="/guide/03-camera/basics"><h4>③ 相机 Camera</h4><p><b class="path-stage path-stage--base">基础</b>透视相机<br><b class="path-stage path-stage--adv">进阶</b>正交与控制器<br><b class="path-stage path-stage--pra">实战</b>四视口观察器</p></a><a class="path-card" href="/guide/04-renderer/basics"><h4>④ 渲染器 Renderer</h4><p><b class="path-stage path-stage--base">基础</b>渲染循环<br><b class="path-stage path-stage--adv">进阶</b>画质与色调映射<br><b class="path-stage path-stage--pra">实战</b>帧率自适应</p></a><a class="path-card" href="/guide/05-geometry/basics"><h4>⑤ 几何体 Geometry</h4><p><b class="path-stage path-stage--base">基础</b>内置几何体<br><b class="path-stage path-stage--adv">进阶</b>自定义顶点属性<br><b class="path-stage path-stage--pra">实战</b>顶点形变动画</p></a><a class="path-card" href="/guide/06-material/basics"><h4>⑥ 材质 Material</h4><p><b class="path-stage path-stage--base">基础</b>四种材质对比<br><b class="path-stage path-stage--adv">进阶</b>物理材质与环境<br><b class="path-stage path-stage--pra">实战</b>材质实验室</p></a><a class="path-card" href="/guide/07-texture/basics"><h4>⑦ 纹理 Texture</h4><p><b class="path-stage path-stage--base">基础</b>UV 与程序化纹理<br><b class="path-stage path-stage--adv">进阶</b>过滤与环绕<br><b class="path-stage path-stage--pra">实战</b>流动纹理</p></a><a class="path-card" href="/guide/08-light/basics"><h4>⑧ 灯光 Light</h4><p><b class="path-stage path-stage--base">基础</b>五种光源<br><b class="path-stage path-stage--adv">进阶</b>阴影映射调优<br><b class="path-stage path-stage--pra">实战</b>三点布光</p></a><a class="path-card" href="/guide/09-animation/basics"><h4>⑨ 动画 Animation</h4><p><b class="path-stage path-stage--base">基础</b>循环与缓动<br><b class="path-stage path-stage--adv">进阶</b>关键帧混合器<br><b class="path-stage path-stage--pra">实战</b>时间轴播放器</p></a><a class="path-card" href="/guide/10-interaction/basics"><h4>⑩ 交互 Interaction</h4><p><b class="path-stage path-stage--base">基础</b>Raycaster 拾取<br><b class="path-stage path-stage--adv">进阶</b>控制器与拖拽<br><b class="path-stage path-stage--pra">实战</b>3D 产品展厅</p></a><a class="path-card" href="/guide/11-capstone/basics"><h4>⑪ 综合实战</h4><p><b class="path-stage path-stage--base">基础</b>架构设计<br><b class="path-stage path-stage--adv">进阶</b>核心实现<br><b class="path-stage path-stage--pra">实战</b>扩展与优化练习</p></a></div><h2 id="给不同读者的建议" tabindex="-1">给不同读者的建议 <a class="header-anchor" href="#给不同读者的建议" aria-label="Permalink to &quot;给不同读者的建议&quot;">​</a></h2><ul><li><strong>零基础读者</strong>：先完成 <a href="/threejs-tutorial-site/guide/00-prerequisites/">0 学前必备</a>的自查清单，确认 JavaScript 与运行环境两块硬性门槛过关，再严格按顺序学习，每个&quot;基础入门&quot;后的小练习务必亲手敲一遍，不要只复制粘贴。</li><li><strong>有其他 3D 引擎经验（Unity / Unreal）的读者</strong>：可快速浏览①–④建立 API 映射，重点阅读⑤–⑧中&quot;与传统引擎的差异&quot;部分。</li><li><strong>有一定 Three.js 基础的读者</strong>：建议从各模块的&quot;进阶应用&quot;切入，用&quot;实战案例&quot;检验掌握程度，遇到盲点再回跳基础篇。</li></ul><h2 id="学习方法提示" tabindex="-1">学习方法提示 <a class="header-anchor" href="#学习方法提示" aria-label="Permalink to &quot;学习方法提示&quot;">​</a></h2><ol><li><strong>先跑起来再改</strong>：打开内嵌演示 → 点&quot;在线编辑&quot; → 每次只改一个参数，观察画面变化。</li><li><strong>用搜索建立索引</strong>：顶部搜索框支持全文检索，遇到具体问题（如&quot;阴影锯齿&quot;）直接搜关键词。</li><li><strong>善用 FAQ</strong>：每章末尾的常见问题覆盖了初学者 80% 的报错场景，卡住时先查它。</li><li><strong>画自己的管线图</strong>：每学完一个模块，尝试默写出它在渲染管线中的位置（本教程的 <a href="/threejs-tutorial-site/guide/01-intro/basics#three-js-的渲染管线">Diagram 示例</a>可作为起点）。</li></ol><p>准备好了吗？从 <a href="/threejs-tutorial-site/guide/01-intro/basics">1.1 基础入门：Three.js 是什么与第一个场景</a> 开始吧。</p>',15)])])}const n=t(h,[["render",p]]);export{c as __pageData,n as default};
